// selectedRangeIndexes computes the indexes selected by a range expression
// over a target of the given length, using the same semantics as read
// slicing.
func selectedRangeIndexes(iex *ast.IndexExpression, length int) ([]int, object.Object) {
	start := 0
	if iex.Index != nil {
		start = int(iex.Index.(*ast.NumberLiteral).Value)
	}
	end := length
	if iex.End != nil {
		end = int(iex.End.(*ast.NumberLiteral).Value)
	}
	step := 1
	if iex.Step != nil {
		step = int(iex.Step.(*ast.NumberLiteral).Value)
	}
	if step == 0 {
		return nil, newError(iex.Token, "slice step cannot be 0")
	}
	if start < 0 {
		start = 0
	}
	if end < 0 {
		end = int(math.Max(float64(length+end), 0))
	} else if end < length {
		end = end
	}
	if step > 0 {
		var out []int
		for i := start; i < end; i += step {
			out = append(out, i)
		}
		return out, NULL
	}
	var out []int
	for i := start; i >= 0; i += step {
		out = append(out, i)
	}
	return out, NULL
}

func evalArrayRangeAssignment(iex *ast.IndexExpression, arrayObject *object.Array, index object.Object, expr object.Object) object.Object {
	indexes, err := selectedRangeIndexes(iex, len(arrayObject.Elements))
	if err != NULL {
		return err
	}
	if arr, ok := expr.(*object.Array); ok {
		if len(arr.Elements) != len(indexes) {
			return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(arr.Elements))
		}
		for i, idx := range indexes {
			arrayObject.Elements[idx] = arr.Elements[i]
		}
		return NULL
	}
	for _, idx := range indexes {
		arrayObject.Elements[idx] = expr
	}
	return NULL
}

func evalStringIndexAssignment(iex *ast.IndexExpression, stringObj object.Object, index object.Object, expr object.Object) object.Object {
	stringObject := stringObj.(*object.String)
	runes := []rune(stringObject.Value)
	idx := index.(*object.Number).Int()

	if iex.IsRange {
		str, ok := expr.(*object.String)
		if !ok {
			return newError(iex.Token, "range assignment expects STRING value, got %s", expr.Type())
		}
		repl := []rune(str.Value)
		indexes, err := selectedRangeIndexes(iex, len(runes))
		if err != NULL {
			return err
		}
		if len(repl) == 1 && len(indexes) > 0 {
			for _, i := range indexes {
				runes[i] = repl[0]
			}
		} else if len(repl) == len(indexes) {
			for i, idx := range indexes {
				runes[idx] = repl[i]
			}
		} else {
			return newError(iex.Token, "range assignment size mismatch: target=%d value=%d", len(indexes), len(repl))
		}
		stringObject.Value = string(runes)
		return NULL
	}

	str, ok := expr.(*object.String)
	if !ok {
		return newError(iex.Token, "index assignment expects STRING value, got %s", expr.Type())
	}
	repl := []rune(str.Value)
	if len(repl) != 1 {
		return newError(iex.Token, "index assignment expects single-character STRING value, got %d characters", len(repl))
	}
	if idx < 0 {
		idx = len(runes) + idx
	}
	if idx < 0 || idx >= len(runes) {
		return newError(iex.Token, "index out of range: %d", idx)
	}
	runes[idx] = repl[0]
	stringObject.Value = string(runes)
